using System;
using System.Linq;
using AlphaPlus.User.Models;
using Fanex.Age.UI;
using Fanex.Age.UI.Components.ShowHideColumn;
using Sunplus.Agent.Utilities;

/// <summary>
/// Base class for renderring context menu to show/hide columns.
/// When overridden these methods, please also call base.ProcessRequest and base.RenderContent.
/// Or base.RegisterCommonScriptObjects, base.RenderContextMenu and base.RenderTableClasses!!!
/// </summary>
public abstract class ContextMenuColumnsBase : TplPage, IContextMenuColumns
{
    /// <summary>
    /// Gets or sets context menu HTML template
    /// </summary>
    protected string ContextMenu;

    /// <summary>
    /// Gets or sets table ID
    /// </summary>
    protected string TableId;

    /// <summary>
    /// Gets or sets array of titles to display on context menu
    /// </summary>
    protected string[] MenuTexts;

    /// <summary>
    /// Gets or sets array of column names need to show/hide
    /// </summary>
    protected string[] ColumnNames;

    /// <summary>
    /// Gets or sets which regions display context menu when right-click
    /// </summary>
    protected string[] MenuRegions;

    /// <summary>
    /// Gets or sets which place contains context menu
    /// </summary>
    protected string MenuContainer;

    /// <summary>
    /// Gets or sets which object implements this class
    /// </summary>
    protected object Implement;

    /// <summary>
    /// Gets or sets cookie name for current context menu
    /// </summary>
    protected string CookieName;

    /// <summary>
    /// Gets or sets table classes to show/hide columns when submitting to server
    /// </summary>
    protected string TableClasses;

    /// <summary>
    /// Base constructor for default implementation of child class
    /// </summary>
    public ContextMenuColumnsBase()
    {
    }

    /// <summary>
    /// When overridden this method, call base.ProcessRequest to render context menu
    /// </summary>
    /// <param name="p"></param>
    public override void ProcessRequest(ref System.Collections.Hashtable p)
    {
        if (this.MenuTexts == null || this.ColumnNames == null)
            throw new Exception("Please initialize MenuTexts and ColumnNames properties!!!");
        else
            this.ContextMenu = this.RenderContextMenu(this.MenuTexts, this.ColumnNames);
    }

    public override object ValidateRequest(System.Collections.Hashtable p)
    {
        return null;
    }

    /// <summary>
    /// When overridden this method, call base.RenderContent to register common javascript objects to support for context menu
    /// </summary>
    /// <param name="writer"></param>
    public override void RenderContent(System.Web.UI.HtmlTextWriter writer)
    {
        if (this.TableId == null || this.MenuRegions == null || this.MenuContainer == null || this.Implement == null)
            throw new Exception("Please initialize TableId, MenuRegions, MenuContainer and Implement properties!!!");
        else
            this.RegisterCommonScriptObjects(this.TableId, this.MenuRegions, this.MenuContainer, this.Implement);
    }

    public override object InvokeData(System.Collections.Hashtable p)
    {
        return null;
    }

    #region IContextMenuColumns Members

    /// <summary>
    /// Renders context menu to show/hide columns
    /// </summary>
    /// <param name="MenuTexts">Array of titles to display on context menu</param>
    /// <param name="cols">Array of column names to show/hide</param>
    /// <returns></returns>
    public string RenderContextMenu(string[] texts, string[] cols)
    {
        this.MenuTexts = texts;
        this.ColumnNames = cols;

        return new ContextMenuColumns().RenderCheckbox(texts, cols);
    }

    /// <summary>
    ///
    /// </summary>
    /// <param name="texts"></param>
    /// <param name="cols"></param>
    /// <param name="colspan"></param>
    /// <param name="showLcs"></param>
    /// <returns></returns>
    public string RenderContextMenu(string[] texts, string[] cols, string[] colspan = null, bool showLcs = false)
    {
        this.MenuTexts = texts;
        this.ColumnNames = cols;

        return new ContextMenuColumns().RenderCheckbox(texts, cols, colspan, showLcs);
    }

    /// <summary>
    /// Registers common javascript objects to support for context menu
    /// </summary>
    /// <param name="tableId">Id of HTML table</param>
    /// <param name="ctxMenuRegionIds">Regions display context menu when right-click</param>
    /// <param name="ctxMenuContainerId">Which place contains context menu</param>
    /// <param name="implement">Which class call this function</param>
    public void RegisterCommonScriptObjects(string tableId, string[] ctxMenuRegionIds, string ctxMenuContainerId, object implement)
    {
        var encodeStr = string.Concat(CurrentUserSession.UserId, CurrentUserSession.CustId, CurrentUserSession.SubAccId, implement.GetType().BaseType.FullName);

        this.CookieName = Encryption.PearsonEncode(encodeStr);
        this.TableId = tableId;
        this.MenuRegions = ctxMenuRegionIds;
        this.MenuContainer = ctxMenuContainerId;
        this.Implement = implement;

        if (this.ColumnNames != null)
            this.TableClasses = this.RenderTableClasses(this.ColumnNames);

        RegisterJavascriptObject(ContextMenuColumns.TableId, tableId);
        RegisterJavascriptObject(ContextMenuColumns.CookiePrefix, this.CookieName);
        RegisterJavascriptObject(ContextMenuColumns.ContextRegionIds, ctxMenuRegionIds);
        RegisterJavascriptObject(ContextMenuColumns.ContextContainerId, ctxMenuContainerId);
    }

    /// <summary>
    /// Renders table classes for show/hide columns, base on HttpCookie request
    /// </summary>
    /// <param name="cols">Array of columns need to show/hide</param>
    /// <param name="hideCols">Array of columns need to hide in cols param</param>
    /// <returns>Classes for show/hide table</returns>
    public string RenderTableClasses(string[] cols, string[] hideCols = null)
    {
        if (this.CookieName == null)
            throw new Exception("Please call RegisterCommonScriptObjects method before this function!!!");
        else
        {
            RegisterJavascriptObject(ContextMenuColumns.HideColumns, IsNotHideColumns(hideCols) ? string.Empty : string.Join(",", hideCols));

            var cookie = Request.Cookies[this.CookieName];
            var sessionId = Request.Cookies["sessionId"];
            var classes = string.Empty;

            if (cookie != null)
            {
                var values = cookie.Value.Split(',');

                for (var i = 0; i < cols.Length; i++)
                {
                    if (cols[i] == "LCS" && (sessionId == null || UserSession.Current == null))
                    {
                        classes += string.Empty;
                    }
                    else
                    {
                        classes += i >= values.Length || values[i].Equals("1") ? string.Concat(" show", cols[i], " .", cols[i], " ") : string.Empty;
                    }
                }
            }
            else
            {
                for (var i = 0; i < cols.Length; i++)
                {
                    if (cols[i] == "LCS" && (sessionId == null || UserSession.Current == null))
                    {
                        classes += string.Empty;
                    }
                    else if (IsNotHideColumns(hideCols))
                    {
                        classes += string.Concat(" show", cols[i], " .", cols[i], " ");
                    }
                    else
                    {
                        classes += !hideCols.Any(col => col == cols[i]) ? string.Concat(" show", cols[i], " .", cols[i], " ") : string.Empty;
                    }
                }
            }

            this.TableClasses = classes;

            return classes;
        }
    }

    private static bool IsNotHideColumns(string[] hideCols)
        => hideCols == null || hideCols.Length == 0;

    #endregion IContextMenuColumns Members
}